<style>
/*Отступы у квиза*/
.t835__col {
    margin-left: 0px !important;
    margin-right: 0px !important;
}
/*Убираем фон в popUp */
.t390 .t-popup__container {
    background: none;
}
</style>

<script>
     var QuizID = '#rec1049428476';  //Прописываем ID Квиза
     var PopWindID = '#rec1049428481';  //Прописываем ID PopUp окна BF503
    //Очищаем popUp контейнер + Добавляем новый клас в POPup
    $(PopWindID + " " + ".t-popup__container").empty();
    //Переносим ZeroBlock в POPup
    $(QuizID).appendTo(PopWindID + " " + ".t-popup__container");
</script>
